			// Team, DSS, Result
			$( ".page-header" ).click(function() {
				$(".sub-menu").toggleClass("sub-menu--reveal");
				$(".page-header__icon").toggleClass("page-header__icon--clicked");
				}
			);

			// Forum, DSS Market outlook (with-image)
			$( ".page-header-img" ).click(function() {
				$(".sub-menu").toggleClass("sub-menu--reveal");
				$(".page-header-img__icon").toggleClass("page-header-img__icon--clicked");
				}
			);

			// Back to top link
			$(window).scroll(function(){
				if ($(this).scrollTop() > 100) {
					$('.back-to-top').fadeIn();
				} else {
					$('.back-to-top').fadeOut();
				}
			});
			$('.back-to-top').click(function(){
				$("html, body").animate({ scrollTop: 0 }, 600);
				return false;
			});

			// Copyright
			$(document).ready(function(){
				$('#js-copyright-years').text('2000-' + (new Date()).getFullYear());
			});			

